<div class="page-head"><div><h1>التقرير المالي الشامل</h1><p>تجميع مجموعات كل صف في صف واحد</p></div><span>V. 2.6</span></div><?php $service=new Alprof\Services\FinancialSummaryService($db);$rows=$service->byGrade(date('Y-m'));?><div class="table-wrap"><table><thead><tr><th>الصف</th><th>المجموعات</th><th>الطلاب</th><th>المستحق</th><th>المسدد</th><th>المتراكم</th><th>صافي المديونية</th><th>التحصيل</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['name'])?></td><td><?=$r['group_count']?></td><td><?=$r['student_count']?></td><td><?=number_format((float)$r['assessed'],2)?></td><td><?=number_format((float)$r['paid'],2)?></td><td><?=number_format((float)$r['arrears'],2)?></td><td><?=number_format((float)$r['net_debt'],2)?></td><td><?=$r['collection_rate']?>%</td></tr><?php endforeach;?></tbody></table></div>